from functools import lru_cache

@lru_cache(None)
def count_neq_numbers(maxi, no=-1):
    if maxi < 10:
        return maxi - (0 < no <= maxi)
    q = maxi // 10
    r = maxi % 10
    ans = 0
    for x in range(10):
        if x == no:
            continue
        if x <= r:
            ans += count_neq_numbers(q, x) + (x != 0)
        else:
            ans += count_neq_numbers(q - 1, x) + (x != 0)
    return ans

def find_kth_neq_number(k):
    lo = 0
    hi = 10**12
    while lo < hi:
        m = (lo + hi) // 2
        if count_neq_numbers(m) < k:
            lo = m + 1
        else:
            hi = m
    return lo

T = int(input())
for _ in range(T):
    k = int(input())
    print(find_kth_neq_number(k))
